/**
 * Deterministic Resolver - Final Production Version
 * Optimized for: Consensus Engine -> Webhook flow
 */

// 1. Extract raw text from the node immediately preceding this one (Consensus Engine)
const rawData = $json.content?.parts?.[0]?.text || $json.text || $json;

let parsed;
try {
  // 2. Clean markdown and parse string into an Object
  parsed = typeof rawData === 'string' 
    ? JSON.parse(rawData.replace(/```json|```/g, "").trim()) 
    : rawData;
} catch (e) {
  // Safe fallback if the AI output is garbled or not JSON
  return [{ 
    json: { 
      error: "Parse error", 
      rawData: String(rawData).substring(0, 100),
      safeMessage: "The AI output could not be parsed into valid JSON."
    } 
  }];
}

// 3. Normalization Logic (Defensive Programming)
const normalizeRisk = (val) => {
  if (val === null || val === undefined) return 0;
  const num = parseFloat(val);
  // Handles the 0.95 vs 95 scale discrepancy
  return (num > 0 && num <= 1) ? Math.round(num * 100) : Math.round(num);
};

// 4. Final Data Assembly with Fallbacks
const finalOutput = {
  // Checks multiple possible keys for risk scores
  riskScore: parsed.riskScore || normalizeRisk(parsed.risk) || normalizeRisk(parsed.risk_score_component) || 0,

  // Robust fallbacks for findings and recommendations
  keyFindings: (parsed.keyFindings || parsed.validated_issues || parsed.findings || []).slice(0, 6),
  recommendations: (parsed.recommendations || parsed.warnings || []).slice(0, 6),

  reasoning: parsed.reasoning || "Consolidated architectural analysis completed successfully.",

  // Handles nested cost objects or flat strings
  monthlyCost: parsed.monthlyCost || parsed.finOps_data?.cost_estimate || parsed.cost_estimate || "N/A"
};

// 5. Return in the standard n8n array format
return [{ json: finalOutput }];
